package com.agrivah.fieldwork;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.net.*;import android.webkit.*;import android.view.*;import java.io.*;import java.time.Instant;import java.util.*;import java.util.concurrent.*;import org.json.*;
public final class MainActivity extends Activity implements LocationListener {
 private WebView web;private Vault vault;private LocationManager locations;private Location latest;private boolean active;private final ExecutorService requests=Executors.newSingleThreadExecutor();private String sessionId=UUID.randomUUID().toString();private String exportData="";private String nextKind="resume";private long lastPoint=0;private ConnectivityManager.NetworkCallback network;
 @Override public void onCreate(Bundle state){super.onCreate(state);vault=new Vault(this);sessionId=vault.get("tracking-session",sessionId);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->web.evaluateJavascript("window.fieldworkBack?.()",null));locations=(LocationManager)getSystemService(LOCATION_SERVICE);web=new WebView(this);setContentView(web);web.setPadding(0,0,0,0);web.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets x=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(x.left,x.top,x.right,x.bottom);}return insets;});
  WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSaveFormData(false);web.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);s.setGeolocationEnabled(false);CookieManager.getInstance().setAcceptCookie(false);WebView.setWebContentsDebuggingEnabled(false);
  web.addJavascriptInterface(new Bridge(),"NativeFieldwork");web.setWebViewClient(new WebViewClient(){
   @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}
   @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest request){Uri u=request.getUrl();String path=u.getPath();if(!"https".equals(u.getScheme())||!"agrivah.com".equals(u.getHost())||path==null||!path.startsWith("/fieldwork/"))return blocked();String file=path.substring("/fieldwork/".length());if(file.isEmpty())file="index.html";if(file.contains("/")||file.contains(".."))return blocked();try{String mime=file.endsWith(".js")?"application/javascript":file.endsWith(".css")?"text/css":file.endsWith(".svg")?"image/svg+xml":file.endsWith(".html")?"text/html":"application/json";Map<String,String> headers=new HashMap<>();headers.put("Cache-Control","no-store");headers.put("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; object-src 'none'; frame-src 'none'; base-uri 'none'");return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,getAssets().open("fieldwork/"+file));}catch(Exception e){return blocked();}}
   @Override public void onPageFinished(WebView v,String url){emit("native-ready",new JSONObject());}
  });web.setWebChromeClient(new WebChromeClient());web.loadUrl(Api.ORIGIN+"/fieldwork/index.html");
  ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);network=new ConnectivityManager.NetworkCallback(){public void onCapabilitiesChanged(Network n,NetworkCapabilities cap){boolean online=cap.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED);if(online)SyncJob.schedule(MainActivity.this);runOnUiThread(()->web.evaluateJavascript("window.dispatchEvent(new Event("+JSONObject.quote(online?"online":"offline")+"))",null));}public void onLost(Network n){runOnUiThread(()->web.evaluateJavascript("window.dispatchEvent(new Event('offline'))",null));}};cm.registerDefaultNetworkCallback(network);SyncJob.schedule(this);
 }
 private WebResourceResponse blocked(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}
 void emit(String kind,JSONObject data){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())web.evaluateJavascript("window.dispatchEvent(new CustomEvent("+JSONObject.quote(kind)+",{detail:"+data+"}))",null);});}
 @Override protected void onResume(){super.onResume();active=true;nextKind="resume";startLocations();}
 @Override protected void onPause(){active=false;locations.removeUpdates(this);super.onPause();}
 @Override protected void onDestroy(){locations.removeUpdates(this);if(network!=null)((ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE)).unregisterNetworkCallback(network);web.removeJavascriptInterface("NativeFieldwork");web.destroy();requests.shutdown();super.onDestroy();}
 @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){web.evaluateJavascript("window.fieldworkBack?.()",null);}
 private boolean signedIn(){try{JSONObject a=new JSONObject(vault.get("account","{}"));JSONObject cached=new JSONObject(vault.get("identity","{}"));JSONObject owner=cached.optJSONObject("account");String until=cached.optString("offlineUntil",cached.optString("expiresAt"));return owner!=null&&a.optString("id").equals(owner.optString("id"))&&!a.optBoolean("mustChangePassword",true)&&Instant.parse(until).toEpochMilli()>System.currentTimeMillis();}catch(Exception e){return false;}}
 private void startLocations(){if(!active||!signedIn()||!"true".equals(vault.get("location-consent","false")))return;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},10);return;}try{if(locations.isProviderEnabled(LocationManager.GPS_PROVIDER))locations.requestLocationUpdates(LocationManager.GPS_PROVIDER,15000,10,this);if(locations.isProviderEnabled(LocationManager.NETWORK_PROVIDER))locations.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,30000,15,this);}catch(SecurityException ignored){}}
 @Override public void onRequestPermissionsResult(int code,String[] p,int[] r){super.onRequestPermissionsResult(code,p,r);if(r.length>0&&r[0]==PackageManager.PERMISSION_GRANTED)startLocations();emit("native-permission",new JSONObject());}
 @Override public void onLocationChanged(Location l){latest=l;if(!active||!signedIn()||System.currentTimeMillis()-lastPoint<10000)return;lastPoint=System.currentTimeMillis();try{JSONObject e=point(l,nextKind,null);nextKind="track";storePoint(e);emit("native-location",e);}catch(Exception ignored){}}
 JSONObject point(Location l,String kind,String record)throws Exception{return new JSONObject().put("id",UUID.randomUUID().toString()).put("sessionId",sessionId).put("kind",kind).put("recordId",record==null?JSONObject.NULL:record).put("lat",l.getLatitude()).put("lng",l.getLongitude()).put("accuracy",(double)l.getAccuracy()).put("at",Instant.ofEpochMilli(l.getTime()).toString()).put("provider",l.getProvider()).put("mock",l.isFromMockProvider());}
 void storePoint(JSONObject e)throws Exception{JSONObject a=new JSONObject(vault.get("account","{}"));String uid=a.optString("id");if(uid.isEmpty())return;vault.put("geo-"+uid+":"+e.getString("id"),e.toString());SyncJob.schedule(this);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==20&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out!=null)out.write(exportData.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){new AlertDialog.Builder(this).setMessage("Export failed. Your original records are retained.").setPositiveButton("OK",null).show();}}exportData="";}
 final class Bridge {
  @JavascriptInterface public boolean online(){ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);NetworkCapabilities cap=cm.getNetworkCapabilities(cm.getActiveNetwork());return cap!=null&&cap.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED);}
  @JavascriptInterface public void exportFile(String name,String value,String type){if(value.length()>10000000)throw new SecurityException("Export too large");runOnUiThread(()->{exportData=value;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(type.split(";",2)[0]);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,20);});}
  @JavascriptInterface public String read(String key){if(!allowedKey(key))return "";return vault.get(key,"");}
  @JavascriptInterface public void write(String key,String value){if(!allowedKey(key)||value.length()>10000000)throw new SecurityException("Invalid local store");vault.put(key,value);if(key.startsWith("state-")){try{JSONObject a=new JSONObject(vault.get("account","{}"));String uid=a.optString("id");if(!key.equals("state-"+uid))return;JSONArray records=new JSONObject(value).optJSONArray("records");if(records!=null)for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);if(uid.equals(r.optString("user"))){String queue="out-"+uid+":"+r.getString("id");if(r.optBoolean("pendingSync")&&r.optJSONObject("serverConflict")==null&&!r.optBoolean("demo"))vault.put(queue,r.toString());else if(!r.optBoolean("pendingSync")){vault.remove(queue);vault.remove("issue-"+r.getString("id"));}}}SyncJob.schedule(MainActivity.this);}catch(JSONException e){throw new IllegalStateException("Draft cannot be queued",e);}}}
  @JavascriptInterface public String receipts(){try{JSONObject result=new JSONObject();JSONObject a=new JSONObject(vault.get("account","{}"));String state=vault.get("state-"+a.optString("id"),"{}");JSONArray records=new JSONObject(state).optJSONArray("records");if(records!=null)for(int i=0;i<records.length();i++){String id=records.getJSONObject(i).getString("id");String receipt=vault.get("receipt-"+id,"");JSONObject entry=receipt.isEmpty()?new JSONObject():new JSONObject(receipt);String issue=vault.get("issue-"+id,"");if(!issue.isEmpty())entry.put("issue",new JSONObject(issue));result.put(id,entry);}return result.toString();}catch(Exception e){return "{}";}}
  @JavascriptInterface public void request(String id,String path,String json){requests.execute(()->{JSONObject result;try{synchronized(Api.LOCK){if(path.equals("_sync")){Api.drain(vault);result=new JSONObject().put("status",200).put("data",new JSONObject(receipts()));}else result=Api.call(vault,path,json==null||json.equals("null")?null:new JSONObject(json));}if(path.equals("login")&&result.getInt("status")==200){sessionId=UUID.randomUUID().toString();vault.put("tracking-session",sessionId);nextKind="login";}if(path.equals("password")||path.equals("bootstrap"))runOnUiThread(()->startLocations());}catch(Exception e){try{result=new JSONObject().put("status",e instanceof Api.AuthRequired?401:0).put("data",new JSONObject().put("error",e instanceof Api.AuthRequired?"unauthorized":"offline"));}catch(JSONException impossible){return;}}try{result.put("id",id);}catch(JSONException ignored){}emit("native-response",result);});}
  @JavascriptInterface public boolean consent(){return "true".equals(vault.get("location-consent","false"));}
  @JavascriptInterface public void locationConsent(boolean consent){vault.put("location-consent",String.valueOf(consent));runOnUiThread(()->{if(consent)startLocations();else locations.removeUpdates(MainActivity.this);});}
  @JavascriptInterface public String location(String kind,String record){if(latest==null||!active||!signedIn()||!"true".equals(vault.get("location-consent","false"))||System.currentTimeMillis()-latest.getTime()>60000)return "";try{JSONObject e=point(latest,kind,record);storePoint(e);return e.toString();}catch(Exception e){return "";}}
  private boolean allowedKey(String key){return key.equals("identity")||key.startsWith("state-");}
 }
}
